package br.ucb.claquete.controller;
import br.ucb.claquete.service.AcervoJdbcService; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/plataformas") public class PlataformaController {private final AcervoJdbcService s;public PlataformaController(AcervoJdbcService s){this.s=s;}@GetMapping public List<Map<String,Object>>listar(){return s.plataformas();}@GetMapping("/{id}")public Map<String,Object>buscar(@PathVariable int id){return s.plataforma(id);}@PostMapping public ResponseEntity<Map<String,Object>>criar(@RequestBody Map<String,Object>r){Map<String,Object>x=s.criarPlataforma(r);return ResponseEntity.created(URI.create("/api/plataformas/"+x.get("id"))).body(x);}@PutMapping("/{id}")public Map<String,Object>atualizar(@PathVariable int id,@RequestBody Map<String,Object>r){return s.atualizarPlataforma(id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void excluir(@PathVariable int id){s.excluirPlataforma(id);}}
